            reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    players_alive = 1 + len(alive)
    total_req = sum(reqs)
    scarce = supply < total_req
    very_tight = supply <= max(reqs) + 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    if prev_bids:
        sorted_bids = sorted(prev_bids)
        moderate_prev = sorted_bids[int(len(sorted_bids) // 2)]

    urgent = hp <= 3 or no_water_days >= 2
    caution = hp <= 5 or no_water_days >= 1

    if not alive:
        if urgent:
            return min(budget, 45.0)
        return min(budget, 18.0)

    if urgent:
        target = max(62.0, moderate_prev + 3.0)
        if highest_prev >= 120.0:
            target = max(target, 82.0)
        if very_tight:
            target = max(target, 88.0)
        return min(budget, target)

    if scarce or very_tight:
        target = max(54.0, moderate_prev + 2.0)
        if highest_prev >= 120.0:
            target = min(target, 76.0)
        if caution:
            target += 6.0
        return min(budget, target)

    if highest_prev >= 120.0 and hp >= 7 and no_water_days == 0:
        return min(budget, 21.0)

    if highest_prev >= 75.0:
        target = 32.0 if hp >= 7 else 44.0
        return min(budget, target)

    target = 36.0
    if caution:
        target = 48.0
    return min(budget, target)

