def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = float(my_status.get('no_water_days', 0.0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o is not None and bool(o.get('alive', False)):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday trace
    prev_bids = []
    prev_pressures = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        # Use hp_after to infer how costly it was to be underbid
        try:
            hp_after = prev.get('hp_after', None)
            if hp_after is not None:
                prev_pressures.append(float(hp_after))
        except Exception:
            pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # If someone was bidding very high yesterday, assume they will keep pressure.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85

    # Base willingness: try to match the aggressive tier only when my HP is safe.
    if high_pressure:
        if my_hp > 3.0 and my_no_water_days >= 2.0:
            target = DAILY_SALARY * 0.35
        else:
            target = DAILY_SALARY * 0.75
    else:
        # Not extreme yesterday: bid enough to avoid being starved.
        if my_hp <= 2.0 or my_no_water_days <= 1.0:
            target = DAILY_SALARY * 0.85
        else:
            target = DAILY_SALARY * 0.55

    # Supply-aware adjustment: when supply is scarce, water is more valuable.
    # Map supply into [0,1] scale.
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        scarcity = 0.5
    scarcity = max(0.0, min(1.0, float(scarcity)))
    target = target * (1.0 + 0.25 * scarcity)

    # Ensure we never exceed budget.
    bid = min(my_budget, target)

    # Safety floor: if we can afford it and we're at risk, bid at least a fraction.
    if my_hp <= 2.0 or my_no_water_days <= 1.0:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.6))

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    yesterday_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                if prev['bid'] > 0:
                    yesterday_bids.append(prev['bid'])

    num_competing_agents = len(alive_opponents) + 1

    base_bid = DAILY_SALARY * 0.5

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            base_bid = max(base_bid, highest_prev_bid + 2)
        else:
            base_bid = max(base_bid, average_prev_bid * 1.05)

    num_water_slots = int(day_context['supply'] // WATER_REQ)

    if num_water_slots < num_competing_agents:
        base_bid *= 1.2
    elif num_water_slots >= num_competing_agents + 1:
        base_bid *= 0.9

    if my_status['hp'] <= 4:
        base_bid *= 1.1
    elif my_status['hp'] <= 6:
        base_bid *= 1.05

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 3 and my_status['hp'] >= 8:
        base_bid *= 1.15
    elif remaining_days <= 3 and my_status['hp'] < 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.85)

    final_bid = max(0.0, min(my_status['budget'], base_bid))

    if len(yesterday_bids) > 0 and final_bid < DAILY_SALARY * 0.25:
        final_bid = max(final_bid, DAILY_SALARY * 0.25)
    elif len(yesterday_bids) == 0 and num_competing_agents > 1:
        final_bid = max(final_bid, DAILY_SALARY * 0.3)

    return final_bid
